    "token_screen_title": "\u0924\u0941\u092e\u094d\u0939\u0940 \u0930\u093e\u0902\u0917\u0947\u0924 \u0906\u0939\u093e\u0924.",
    "token_screen_sub": "\u0915\u0943\u092a\u092f\u093e \u0930\u0942\u092e \u0967\u0966\u096a \u092c\u093e\u0939\u0947\u0930 \u092c\u0938\u093e. \u0921\u0949\u0915\u094d\u091f\u0930\u093e\u0902\u0928\u093e \u092e\u093e\u0939\u093f\u0924\u0940 \u092e\u093f\u0933\u093e\u0932\u0940 \u0906\u0939\u0947.",
    "help_text": "\u0915\u0943\u092a\u092f\u093e \u091c\u0935\u0933\u092a\u093e\u0938\u091a\u094d\u092f\u093e \u0915\u0930\u094d\u092e\u091a\u093e\u0931\u094d\u092f\u093e\u0902\u091a\u0940 \u092e\u0926\u0924 \u0918\u094d\u092f\u093e.",
    "scan_with_camera": "\u0915\u094d\u092f\u0942\u0906\u0930 \u0915\u094b\u0921 \u0915\u0945\u092e\u0947\u0931\u094d\u092f\u093e\u0938\u092e\u094b\u0930 \u0920\u0947\u0935\u093e",
