    "Severe": "చాలా తీవ్రమైనది",
    "Did the pain come on suddenly or gradually?": "నొప్పి హఠాత్తుగా వచ్చిందా లేక నెమ్మదిగా పెరిగిందా?",
    "Choose how the pain started.": "నొప్పి ఎలా ప్రారంభమైందో ఎంచుకోండి.",
    "Sudden (came out of nowhere)": "హఠాత్తుగా (ఒక్కసారిగా వచ్చింది)",
    "Gradually (got worse over time)": "నెమ్మదిగా (సమయంతో పాటు పెరిగింది)",
    "Comes and goes": "వస్తూ పోతూ ఉంటుంది",
    "Does eating make the pain worse?": "అన్నం తిన్న తర్వాత నొప్పి పెరుగుతుందా?",
    "Think about whether food or drink affects the pain.": "ఆహారం తిన్నాక నొప్పి పెరుగుతుందో లేదో ఆలోచించండి.",
    "Yes – worse after eating": "అవును – తిన్న తర్వాత పెరుగుతుంది",
    "Yes – worse before eating": "అవును – తినకముందు పెరుగుతుంది",
    "No difference": "తేడా ఏమీ లేదు",
    "Not sure": "ఖచ్చితంగా తెలియదు",
    "Do you have nausea or vomiting?": "వాంతులు లేదా వికారం ఉందా?",
    "Select what you have experienced.": "మీకు ఉన్న అనుభవాన్ని ఎంచుకోండి.",
    "Nausea only (no vomiting)": "వికారం మాత్రమే (వాంతి అవ్వలేదు)",
    "Vomiting occurred": "వాంతి అయింది",
    "Both nausea and vomiting": "వికారం మరియు వాంతులు రెండూ",
    "No – neither": "లేదు – రెండూ లేవు",
    "Do you also have fever?": "మీకు జ్వరం కూడా ఉందా?",
    "Slight warmth but not sure": "వేడిగా ఉంది కానీ ఖచ్చితంగా తెలియదు",
    "Any change in your bowel movements (motions)?": "మోషన్ వెళ్లడంలో ఏమైనా మార్పు ఉందా?",
    "This helps the doctor understand what is happening.": "ఇది డాక్టర్‌కు పరిస్థితిని అర్థం చేసుకోవడానికి సహాయపడుతుంది.",
    "Loose stools / Diarrhea": "విరేచనాలు / మోషన్స్",
    "Constipation (no motion)": "మలబద్ధకం",
    "Normal": "సాధారణం",
    "Blood in stool": "మోషన్ లో రక్తం పడటం",
    "Have you had this pain before?": "ఇంతకు ముందు ఎప్పుడైనా ఈ నొప్పి వచ్చిందా?",
    "Tell us if this is a recurring problem.": "ఇది పదే పదే వచ్చే సమస్యా కాదో చెప్పండి.",
    "First time ever": "మొదటి సారి వచ్చింది",
    "Yes – happened before, goes away on its own": "అవును – గతంలో వచ్చింది, తనంతట తానే తగ్గింది",
    "Yes – ongoing problem": "అవును – తరచూ వచ్చే సమస్య",
    "Yes – diagnosed condition (e.g. Gastritis, IBS)": "అవును – డాక్టర్ గుర్తించిన సమస్య",

    // Telugu Cough Flow
    "How long have you been coughing?": "దగ్గు ఎన్ని రోజుల నుండి ఉంది?",
    "Select the number of days.": "రోజుల సంఖ్యను ఎంచుకోండి.",
    "Less than 2 days": "2 రోజుల కంటే తక్కువ",
    "3 – 5 days": "3–5 రోజులు",
    "5 – 7 days": "5–7 రోజులు",
    "What kind of cough do you have?": "మీకు ఎటువంటి దగ్గు ఉంది?",
    "Select the option that best describes your cough.": "మీ దగ్గు రకాన్ని ఎంచుకోండి.",
    "Dry cough (no mucus)": "పొడి దగ్గు (కఫం లేదు)",
    "Wet cough with white/clear mucus": "తెల్లటి కఫంతో కూడిన దగ్గు",
    "Yellow or green mucus (phlegm)": "పసుపు లేదా ఆకుపచ్చ కఫం",
    "Blood in mucus (streaks)": "కఫంలో రక్తం",
    "How much is the cough disturbing you?": "దగ్గు మిమ్మల్ని ఎంత ఇబ్బంది పెడుతోంది?",
    "Rate the impact on your daily routine.": "మీ రోజువారీ పనులపై దీని ప్రభావాన్ని తెలియజేయండి.",
    "Do you have fever along with the cough?": "దగ్గుతో పాటు జ్వరం ఉందా?",
    "Yes – high fever": "అవును – తీవ్రమైన జ్వరం",
    "Yes – mild fever": "అవును – స్వల్ప జ్వరం",
    "No fever": "జ్వరం లేదు",
    "Do you have any difficulty breathing?": "ఆయాసం లేదా శ్వాస తీసుకోవడం కష్టంగా ఉందా?",
    "This is important for the doctor to know.": "ఇది డాక్టర్ తెలుసుకోవడం చాలా ముఖ్యం.",
    "Shortness of breath at rest": "కూర్చున్నా కూడా శ్వాస ఆడకపోవడం",
    "Shortness of breath on walking": "నడిస్తే ఆయాసం రావడం",
    "Mild breathlessness": "కొద్దిగా ఆయాసం",
    "No – breathing is fine": "లేదు – శ్వాస బాగానే ఉంది",
    "Do you have a sore throat or runny nose?": "గొంతు నొప్పి లేదా ముక్కు కారడం ఉందా?",
    "Sore throat only": "గొంతు నొప్పి మాత్రమే",
    "Runny nose only": "ముక్కు కారడం మాత్రమే",
    "Both sore throat and runny nose": "గొంతు నొప్పి మరియు ముక్కు కారడం రెండూ",
    "Neither": "ఏదీ లేదు",
    "Have you been around someone who was sick recently?": "ఇటీవల ఎవరైనా అనారోగ్యంతో ఉన్నవారి వద్దకు వెళ్లారా?",
    "For example, family member or colleague with similar symptoms.": "ఉదాహరణకు కుటుంబ సభ్యులు లేదా సహోద్యోగులు.",
    "Do you feel any chest pain or tightness with the cough?": "దగ్గుతో పాటు ఛాతీ నొప్పి లేదా పట్టేసినట్లు ఉందా?",
    "Yes – chest pain": "అవును – ఛాతీ నొప్పి",
    "Yes – just tightness": "అవును – ఛాతీ పట్టేయడం మాత్రమే",

    // Telugu Fever Questions
    "How long have you had the fever?": "జ్వరం ఎన్ని రోజుల నుండి ఉంది?",
    "Select how many days you have had the fever.": "జ్వరం రోజుల సంఖ్యను ఎంచుకోండి.",
    "How high is the fever?": "జ్వరం ఎంత ఎక్కువగా ఉంది?",
    "Approximate temperature if known.": "తెలిస్తే సుమారు ఉష్ణోగ్రత.",
    "Mild (99 – 100°F / 37.2 – 37.8°C)": "తేలికపాటి జ్వరం (99 – 100°F)",
    "Moderate (100 – 102°F / 37.8 – 38.9°C)": "మధ్యస్థ జ్వరం (100 – 102°F)",
