    "Yes – severe chills": "అవును – తీవ్రమైన చలి",
    "Yes – mild chills": "అవును – స్వల్ప చలి",
    "No chills": "చలి లేదు",
    "How did the fever start?": "జ్వరం ఎలా ప్రారంభమైంది?",
    "Sudden – very quickly": "ఒక్కసారిగా – చాలా వేగంగా",
    "Gradually over a day": "ఒక రోజులో నెమ్మదిగా",
    "Comes and goes (intermittent)": "వస్తూ పోతూ ఉంది",
    "Do you also have a cough?": "మీకు దగ్గు కూడా ఉందా?",
    "Yes – dry cough": "అవును – పొడి దగ్గు",
    "Yes – cough with phlegm": "అవును – కఫంతో కూడిన దగ్గు",
    "No cough": "దగ్గు లేదు",
    "Do you have body ache or joint pain with the fever?": "జ్వరంతో పాటు ఒళ్ళు నొప్పులు లేదా కీళ్ళ నొప్పులు ఉన్నాయా?",
    "Yes – severe body ache": "అవును – తీవ్రమైన ఒళ్ళు నొప్పులు",
    "Yes – mild ache": "అవును – స్వల్ప ఒళ్ళు నొప్పులు",
    "Have you noticed any skin rash or red spots?": "చర్మంపై ఎర్రటి మచ్చలు లేదా దద్దుర్లు ఉన్నాయా?",
    "This can help identify certain conditions.": "ఇది వ్యాధిని గుర్తించడంలో సహాయపడుతుంది.",
    "Yes – rash appeared": "అవును – దద్దుర్లు వచ్చాయి",
    "No rash": "దద్దుర్లు లేవు",
    "Do you have vomiting or loose stools with the fever?": "జ్వరంతో పాటు వాంతులు లేదా విరేచనాలు ఉన్నాయా?",
    "Vomiting only": "వాంతులు మాత్రమే",
    "Loose stools only": "విరేచనాలు మాత్రమే",
    "Both": "రెండూ",
