    "Travel history is sometimes relevant for infections.": "ఇన్ఫెక్షన్లను గుర్తించడానికి ప్రయాణ వివరాలు ముఖ్యం.",
    "Yes – in last 2 weeks": "అవును – గత 2 వారాల్లో",

    // Telugu Headache Questions
