    "Temples (sides of head)": "కణతల వద్ద (తల ఇరువైపులా)",
    "Back of head": "తల వెనుక భాగం",
    "Top of head": "మాడు భాగంలో (తల పైన)",
    "One side only (Left or Right)": "ఒక వైపు మాత్రమే (ఎడమ లేదా కుడి)",
    "Entire head": "తల అంతటా",
    "How severe is the headache?": "తలనొప్పి ఎంత తీవ్రంగా ఉంది?",
    "How did the headache start?": "తలనొప్పి ఎలా ప్రారంభమైంది?",
    "Sudden – very intense immediately": "ఒక్కసారిగా – తీవ్రమైన నొప్పి",
    "Gradually got worse": "నెమ్మదిగా పెరిగింది",
    "Throbbing / pulsating": "లాగుతున్నట్లు / టీట్లు పెడుతున్నట్లు",
    "Constant pressure / dull ache": "ఒత్తిడిగా / మందకొడిగా ఉన్న నొప్పి",
    "Does light or noise bother you when you have the headache?": "తలనొప్పి ఉన్నప్పుడు వెలుతురు లేదా శబ్దం ఇబ్బంది పెడుతోందా?",
    "This can help the doctor understand the type of headache.": "ఇది తలనొప్పి రకాన్ని అర్థం చేసుకోవడానికి సహాయపడుతుంది.",
    "Yes – both light and noise": "అవును – వెలుతురు మరియు శబ్దం రెండూ",
    "Yes – light only": "అవును – వెలుతురు మాత్రమే",
    "Yes – noise only": "అవును – శబ్దం మాత్రమే",
    "No – neither bothers me": "లేదు – ఏదీ ఇబ్బంది పెట్టదు",
    "Do you have nausea or vomiting along with the headache?": "తలనొప్పితో పాటు వికారం లేదా వాంతులు ఉన్నాయా?",
    "Yes – nausea": "అవును – వికారం మాత్రమే",
    "Yes – vomiting too": "అవును – వాంతి కూడా అయింది",
