    "Select all that apply (most significant).": "సరిపోయే ఐచ్ఛికాన్ని ఎంచుకోండి.",
    "Stress or tension": "మానసిక ఒత్తిడి",
    "Lack of sleep": "నిద్రలేమి",
    "Dehydration (not enough water)": "నీరు సరిగ్గా తాగకపోవడం",
    "Screen time (phone/computer)": "స్క్రీన్ సమయం (ఫోన్/కంప్యూటర్)",
    "No clear trigger": "స్పష్టమైన కారణం లేదు",
    "Have you had similar headaches before?": "గతంలో కూడా ఇలాంటి తలనొప్పి వచ్చిందా?",
    "Yes – diagnosed as Migraine": "అవును – మైగ్రేన్ అని నిర్ధారించారు",
    "Yes – recurring but not diagnosed": "అవును – తరచూ వస్తుంది కానీ పరీక్షించుకోలేదు",
    "First time this severe": "మొదటిసారి ఇంత తీవ్రంగా వచ్చింది",
